import { ExpandLess, ExpandMore } from "@airbus/icons/react";
import { Row, RowData, Table } from "@tanstack/react-table";
import * as React from "react";
import IconButton from "../../IconButton";

export const EXPAND_COLUMN_ID = "__table__expand__";

const ExpandHeader = <T extends RowData>({ table }: { table: Table<T> }) => {
  const handleToggleExpand = (event: React.MouseEvent<HTMLButtonElement>) => {
    event.stopPropagation();
    table.toggleAllRowsExpanded();
  };

  if (!table.getCanSomeRowsExpand()) return null;
  else
    return (
      <IconButton
        size="xsmall"
        variant="ghost"
        onClick={handleToggleExpand}
        title={"Toggle Row Expanded header"}
      >
        {table.getIsAllRowsExpanded() ? <ExpandLess /> : <ExpandMore />}
      </IconButton>
    );
};

export const ExpandRow = <T extends RowData>(row: Row<T>) => {
  const handleToggleExpand = (event: React.MouseEvent<HTMLButtonElement>) => {
    event.stopPropagation();
    row.toggleExpanded();
  };

  if (!row.getCanExpand()) return null;
  else
    return (
      <IconButton
        size="xsmall"
        variant="ghost"
        onClick={handleToggleExpand}
        title={"Toggle Row Expanded"}
      >
        {row.getIsExpanded() ? <ExpandLess /> : <ExpandMore />}
      </IconButton>
    );
};

export const expandableColumn = {
  id: EXPAND_COLUMN_ID,
  header: <T extends RowData>({ table }: { table: Table<T> }) => (
    <ExpandHeader table={table} />
  ),
  disableResizing: true,
  disableSortBy: true,
  cell: <T extends RowData>({ row }: { row: Row<T> }) => <ExpandRow {...row} />,
};
